"use client";
import { useId } from "react";
import {
  Area,
  AreaChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";
import { CURSOR, formatNumber, useChartHover } from "./chart-card";
import { ChartActiveDot } from "./chart-active-dot";
import { AREA_DEMO_RANGES } from "./chart-demo-data";
import {
  type ChartCommonProps,
  ChartFrame,
  type ChartRange,
  chartAxis,
  ink,
  numeric,
  PeriodSelect,
  StatTiles,
  shortNumber,
  sum,
  useChartRange,
} from "./pro-chart";

export interface AreaSeries {
  key: string;
  label: string;
  tone?: number;
  color?: string;
}
export interface AreaPoint {
  label: string;
  [series: string]: string | number;
}
export interface AreaChartRange extends ChartRange {
  data: AreaPoint[];
}
export interface AreaChartCardProps extends ChartCommonProps {
  data?: AreaPoint[];
  series?: AreaSeries[];
  ranges?: AreaChartRange[];
  variant?: "stacked" | "overlap" | "percent";
  shape?: "smooth" | "sharp";
  stacked?: boolean;
  prefix?: string;
  tiles?: boolean;
}
const DEFAULT_SERIES: AreaSeries[] = [
  { key: "organic", label: "Organic" },
  { key: "referral", label: "Referral" },
  { key: "paid", label: "Paid" },
];
export const AREA_DATA: AreaPoint[] = AREA_DEMO_RANGES[0]!.data;
const DEMO_RANGES: AreaChartRange[] = AREA_DEMO_RANGES;

export function AreaChartCard({
  data,
  series = DEFAULT_SERIES,
  ranges: supplied,
  title = "Visitors",
  variant: explicit,
  stacked = true,
  shape = "smooth",
  prefix = "",
  tiles = true,
  ...props
}: AreaChartCardProps = {}) {
  const ranges = supplied ?? (data ? undefined : DEMO_RANGES),
    period = useChartRange(ranges, props.defaultRange, props.onRangeChange),
    points = period.current?.data ?? data ?? AREA_DATA;
  const variant = explicit ?? (stacked ? "stacked" : "overlap"),
    reduced = useHydratedReducedMotion(),
    id = useId(),
    hover = useChartHover();
  const colors = series.map(
    (s, i) => s.color ?? (s.tone ? `var(--color-chart-${s.tone})` : ink(i)),
  );
  const totals = series.map((s) => sum(points.map((p) => numeric(p[s.key])))),
    point = hover.activeIndex != null ? points[hover.activeIndex] : undefined;
  const value = point
    ? sum(series.map((s) => numeric(point[s.key])))
    : (period.current?.headline ??
      props.headline ??
      (variant === "overlap" ? (totals[0] ?? 0) : sum(totals)));
  const format = props.format ?? ((n: number) => prefix + formatNumber(n));
  return (
    <ChartFrame
      title={point?.label ?? title}
      value={value}
      format={format}
      delta={point ? undefined : (period.current?.delta ?? props.delta)}
      animateNumber
      pulseKey={hover.activeIndex}
      className={props.className}
      action={
        <PeriodSelect
          ranges={ranges}
          selected={period.id}
          onChange={(id) => {
            hover.clear();
            period.select(id);
          }}
          label={period.current?.label ?? props.range}
        />
      }
      footer={
        tiles && (
          <StatTiles
            items={series.map((s, i) => ({
              label: s.label,
              value: format(point ? numeric(point[s.key]) : (totals[i] ?? 0)),
              color: colors[i],
            }))}
            responsive
            fillLastOdd
          />
        )
      }
    >
      <div className="h-[196px] w-full min-w-0">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart
            data={points}
            stackOffset={variant === "percent" ? "expand" : "none"}
            margin={{ top: 4, right: 6, bottom: 0, left: 0 }}
            {...hover.handlers}
          >
            <defs>
              {series.map((s, i) => (
                <linearGradient
                  id={`${id}-${s.key}`}
                  key={s.key}
                  x1="0"
                  x2="0"
                  y1="0"
                  y2="1"
                >
                  <stop offset="0%" stopColor={colors[i]} stopOpacity={0.55} />
                  <stop
                    offset="100%"
                    stopColor={colors[i]}
                    stopOpacity={0.04}
                  />
                </linearGradient>
              ))}
            </defs>
            <CartesianGrid
              vertical={false}
              stroke="var(--color-chart-track)"
              strokeDasharray="4 4"
            />
            <YAxis
              {...chartAxis}
              width={44}
              tickCount={variant === "percent" ? 5 : 4}
              domain={variant === "percent" ? [0, 1] : [0, "auto"]}
              tickFormatter={(n) =>
                variant === "percent"
                  ? `${Math.round(n * 100)}%`
                  : prefix + shortNumber(n)
              }
            />
            <XAxis
              interval="preserveStartEnd"
              {...chartAxis}
              dataKey="label"
              tick={{ ...chartAxis.tick, fontSize: 13 }}
              tickMargin={12}
            />
            <Tooltip content={() => null} cursor={CURSOR} />
            {series.map((s, i) => (
              <Area
                key={s.key}
                type={shape === "sharp" ? "linear" : "monotone"}
                dataKey={s.key}
                stackId={variant === "overlap" ? undefined : "total"}
                stroke={
                  s.color ??
                  (s.tone
                    ? `var(--color-chart-${s.tone}-active)`
                    : ink(i).replace(")", "-active)"))
                }
                fill={`url(#${id}-${s.key})`}
                strokeWidth={2}
                activeDot={
                  <ChartActiveDot
                    pulse={false}
                    coreRadius={4}
                    coreStrokeWidth={2}
                    fill={
                      s.color ??
                      (s.tone
                        ? `var(--color-chart-${s.tone}-active)`
                        : ink(i).replace(")", "-active)"))
                    }
                  />
                }
                isAnimationActive={!reduced}
                animationDuration={450}
                animationEasing="ease"
              />
            ))}
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </ChartFrame>
  );
}
